"use client";

import { useRef } from "react";
import { useFrame } from "@react-three/fiber";
import * as THREE from "three";
import { Sphere } from "@react-three/drei";

export default function IdentityPlanetVisual() {
  const outerCoreRef = useRef<THREE.Mesh>(null);

  // 🌀 دوران داخلي خاص بالشكل البصري لزيادة التعقيد السينمائي
  useFrame((_, delta) => {
    if (outerCoreRef.current) {
      outerCoreRef.current.rotation.x += delta * 0.1;
      outerCoreRef.current.rotation.y -= delta * 0.15;
    }
  });

  return (
    <group>
      {/* 🔸 النواة الصلبة الداخلية */}
      <Sphere args={[1, 64, 64]}>
        <meshStandardMaterial
          color="#ff8c00"
          metalness={0.7}
          roughness={0.3}
          emissive="#331a00"
        />
      </Sphere>

      {/* 🌐 القشرة الخارجية (Wireframe) اللي بتدي طابع الجذور الرقمية */}
      <Sphere ref={outerCoreRef} args={[1.05, 32, 32]}>
        <meshStandardMaterial
          color="#ffd4a3"
          wireframe
          transparent
          opacity={0.3}
          emissive="#ffd4a3"
          emissiveIntensity={0.5}
        />
      </Sphere>
    </group>
  );
}