"use client";

import { useRef } from "react";
import { useFrame } from "@react-three/fiber";
import * as THREE from "three";

export default function ShootingStars() {
  const groupRef = useRef<THREE.Group>(null);

  // دوران بطيء جداً لمجموعة النجوم المتساقطة لإعطاء إحساس بالحركة
  useFrame(() => {
    if (groupRef.current) {
      groupRef.current.rotation.y += 0.0005;
    }
  });

  return (
    <group ref={groupRef}>
      {/* حالياً هذا المكون فارغ بصرياً لضمان عدم وجود أخطاء في الـ TypeScript.
        سيتم برمجة هندسة النجوم المتساقطة (Shooting Stars Geometry) هنا في مرحلة הـ Cinematic Polish.
      */}
    </group>
  );
}