"use client";

import { useState, useCallback } from "react";
import { Canvas } from "@react-three/fiber";
import { Suspense } from "react";
import { OrbitControls, Stars } from "@react-three/drei";
import * as THREE from "three";

import { useExperience } from "../engine/experienceStore";
import TheSolarSystem from "../components/3d/systems/TheSolarSystem";
import CinematicCameraController from "../components/3d/core/CinematicCameraController";
import ShootingStars from "../components/3d/effects/ShootingStars";
import IntroPortal from "../components/ui/IntroPortal";

export default function Home() {
  const [introState, setIntroState] = useState<"active" | "warping" | "completed">("active");
  const [cameraFocus, setCameraFocus] = useState<THREE.Vector3 | null>(null);

  const handleIntroIgnition = useCallback(() => {
    setIntroState("warping");
    setTimeout(() => {
      setIntroState("completed");
    }, 1500);
  }, []);

  return (
    <main className="w-screen h-screen relative overflow-hidden bg-black">

      {/* ================= 3D WORLD (النجوم في الخلفية دائماً) ================= */}
      <div className="absolute inset-0 w-full h-full z-0">
        <Canvas
          shadows
          camera={{ position: [0, 20, 500], fov: 50 }}
          gl={{ antialias: true, toneMapping: THREE.ACESFilmicToneMapping }}
        >
          <color attach="background" args={["#000000"]} />
          <fog attach="fog" args={["#000000", introState === "completed" ? 300 : 500, 2000]} />
          <ambientLight intensity={0.1} />

          <Suspense fallback={null}>
            {/* 🌌 النجوم موجودة هنا وتعمل منذ الثانية الأولى */}
            <Stars radius={300} depth={60} count={6000} factor={7} saturation={0} fade speed={introState === "warping" ? 12 : 0.5} />
            
            {introState !== "active" && <ShootingStars />}

            {introState === "completed" && (
              <TheSolarSystem onPlanetFocus={(data) => setCameraFocus(data ? data.position : null)} />
            )}

            {introState !== "active" && (
               <CinematicCameraController focusTarget={cameraFocus} isWarping={introState === "warping"} />
            )}
          </Suspense>

          {introState === "completed" && (
            <OrbitControls makeDefault enableDamping dampingFactor={0.05} minDistance={50} maxDistance={800} />
          )}
        </Canvas>
      </div>

      {/* ================= INTRO LAYER (الواجهة الأمامية الشفافة) ================= */}
      {introState === "active" && (
        <div className="absolute inset-0 z-50">
          <IntroPortal onEnter={handleIntroIgnition} />
        </div>
      )}

    </main>
  );
}
