"use client";

import React, { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';

export default function IntroPortal({ onEnter }: { onEnter: () => void }) {
  const [state, setState] = useState<'idle' | 'hover' | 'active'>('idle');
  const [isWarping, setIsWarping] = useState(false);
  const [isLoaded, setIsLoaded] = useState(false);
  
  const timerRef = useRef<NodeJS.Timeout | null>(null);

  const ASSETS = {
    idle: 'https://raw.githubusercontent.com/mizoamin/mizo-assets-media-1/main/brand_assets/professional-headshots-and-profile-pics/mizo-state1-off.png',
    hover: 'https://raw.githubusercontent.com/mizoamin/mizo-assets-media-1/main/brand_assets/professional-headshots-and-profile-pics/mizo-state2-ready.png',
    active: 'https://raw.githubusercontent.com/mizoamin/mizo-assets-media-1/main/brand_assets/professional-headshots-and-profile-pics/mizo-state3-active.png',
  };

  useEffect(() => {
    let loadedCount = 0;
    const totalImages = Object.keys(ASSETS).length;

    Object.values(ASSETS).forEach(src => {
      const img = new Image();
      img.src = src;
      img.onload = () => {
        loadedCount++;
        if (loadedCount === totalImages) {
          setIsLoaded(true);
        }
      };
    });

    return () => {
      if (timerRef.current) clearTimeout(timerRef.current);
    };
  }, []);

  const handlePointerDown = (e: React.PointerEvent | React.MouseEvent) => {
    e.preventDefault();
    if (isWarping || !isLoaded) return;
    
    setState('active');
    
    // الانتظار لمدة 1.8 ثانية (توقيت سينمائي لرؤية النظارة المضيئة)
    timerRef.current = setTimeout(() => {
      setIsWarping(true);
      
      // التلاشي الناعم ثم تسليم القيادة لملف page.tsx
      setTimeout(() => {
        if (typeof onEnter === 'function') {
          onEnter();
        }
      }, 1200); 
    }, 1800); 
  };

  const handlePointerUp = (e: React.PointerEvent | React.MouseEvent) => {
    e.preventDefault();
    if (isWarping || !isLoaded) return;
    if (timerRef.current) clearTimeout(timerRef.current);
    setState('hover');
  };

  const handlePointerLeave = (e: React.PointerEvent | React.MouseEvent) => {
    e.preventDefault();
    if (isWarping || !isLoaded) return;
    if (timerRef.current) clearTimeout(timerRef.current);
    setState('idle');
  };

  return (
    <AnimatePresence>
      {!isWarping && (
        <motion.div
          className="fixed inset-0 flex flex-col items-center justify-between"
          style={{ 
            background: 'transparent', 
            height: '100dvh', 
            width: '100vw', 
            overflow: 'hidden',
            zIndex: 999999
          }}
          exit={{ opacity: 0, scale: 1.05, filter: "blur(15px)" }}
          transition={{ duration: 1.2, ease: "easeInOut" }}
        >
          {/* حماية الواجهة ومنع الفلاش الرخيص */}
          <style dangerouslySetInnerHTML={{__html: `
            * {
              -webkit-tap-highlight-color: transparent !important;
              -webkit-touch-callout: none !important;
              user-select: none !important;
              -webkit-user-select: none !important;
              outline: none !important;
            }
            img { pointer-events: none !important; }
            body { overscroll-behavior: none; }
          `}} />

          {/* حاوية الصور */}
          <div 
            className="relative w-full flex flex-col justify-end items-center pt-8 cursor-pointer"
            style={{ height: '70dvh' }}
            onPointerEnter={() => !isWarping && isLoaded && setState('hover')}
            onPointerLeave={handlePointerLeave}
            onPointerDown={handlePointerDown}
            onPointerUp={handlePointerUp}
            onPointerCancel={handlePointerUp}
            onContextMenu={(e) => e.preventDefault()}
          >
            <motion.div 
              className="relative w-full max-w-[650px] h-full"
              initial={{ opacity: 0 }}
              animate={{ opacity: isLoaded ? 1 : 0 }}
              transition={{ duration: 0.5 }}
            >
              {/* الصور النقية 100% بدون أي فلاتر رخيصة */}
              <motion.img src={ASSETS.idle} className="absolute bottom-0 left-0 w-full h-full object-contain object-bottom z-10" animate={{ opacity: state === 'idle' ? 1 : 0 }} transition={{ duration: 0.8 }} alt="Mizo" />
              <motion.img src={ASSETS.hover} className="absolute bottom-0 left-0 w-full h-full object-contain object-bottom z-20" animate={{ opacity: state === 'hover' ? 1 : 0 }} transition={{ duration: 0.5 }} alt="Mizo Ready" />
              <motion.img src={ASSETS.active} className="absolute bottom-0 left-0 w-full h-full object-contain object-bottom z-30" animate={{ opacity: state === 'active' ? 1 : 0 }} transition={{ duration: 0.3 }} alt="Mizo Active" />
            </motion.div>
          </div>

          {/* النصوص (الحل الجذري لاختفاء MIZO) */}
          <div className="w-full flex flex-col items-center justify-center pb-8 z-50 pointer-events-none" style={{ height: '30dvh', fontFamily: '"Segoe UI", Roboto, Helvetica, Arial, sans-serif' }}>
            
            {/* استخدام whitespace-nowrap و flex-shrink-0 يمنع المتصفح من إخفاء الكلمة */}
            <div className="flex items-center gap-4 mb-3 whitespace-nowrap flex-shrink-0">
              <h1 className="font-black text-white tracking-[0.15em] m-0 leading-none text-5xl md:text-7xl">MIZO</h1>
              <h1 className="font-black text-transparent tracking-[0.15em] m-0 leading-none text-5xl md:text-7xl" style={{ WebkitTextStroke: '2px white' }}>AMIN</h1>
            </div>
            
            <div className="flex items-center gap-4 flex-shrink-0 whitespace-nowrap">
              <span className="w-10 md:w-16 h-px bg-white/30"></span>
              <p className="text-white/70 tracking-[0.4em] md:tracking-[0.6em] text-[10px] md:text-[13px] font-bold uppercase m-0">SPATIAL DIGITAL DOMAIN</p>
              <span className="w-10 md:w-16 h-px bg-white/30"></span>
            </div>

            <div className="mt-8 h-6 flex items-center justify-center flex-shrink-0">
              {!isLoaded ? (
                 <p className="text-white/40 tracking-[0.3em] md:tracking-[0.5em] text-[9px] md:text-[11px] uppercase m-0 animate-pulse">CALIBRATING...</p>
              ) : (
                <motion.p 
                  className="text-white/40 tracking-[0.3em] md:tracking-[0.5em] text-[9px] md:text-[11px] uppercase m-0"
                  animate={{ opacity: state === 'active' ? [0.4, 1, 0.4] : 1 }}
                  transition={{ duration: 1.5, repeat: state === 'active' ? Infinity : 0 }}
                >
                  {state === 'active' ? 'NEURAL LINK ESTABLISHED...' : 'HOLD / CLICK TO ENTER'}
                </motion.p>
              )}
            </div>
          </div>
        </motion.div>
      )}
    </AnimatePresence>
  );
}
